  function qpath(a,b){var x1=a.x*10,y1=a.y*5,x2=b.x*10,y2=b.y*5,mx=(x1+x2)/2,my=Math.min(y1,y2)-Math.min(90,Math.abs(x2-x1)*.12+20);return'M '+x1+' '+y1+' Q '+mx+' '+my+' '+x2+' '+y2;}
  function mapSvg(){var target=mapPoint(selected.lat,selected.lon),arcs=issuerTokens(selected).map(function(k){var v=ISSUER_POS[k]||ISSUER_POS.Other,p=mapPoint(v[0],v[1]);return'<path class="snw-arc is-selected" d="'+qpath(p,target)+'"/>';}).join('');var pts=DATA.map(function(p){var q=mapPoint(p.lat,p.lon),on=p.id===selected.id;return'<g class="snw-point '+(on?'is-selected':'')+'" data-snw-id="'+esc(p.id)+'" data-status="'+esc(p.status)+'" transform="translate('+(q.x*10).toFixed(1)+' '+(q.y*5).toFixed(1)+')"><circle r="7"></circle><circle r="3.2"></circle><text x="9" y="3">'+esc(p.name)+'</text></g>';}).join('');return'<svg viewBox="0 0 1000 500" preserveAspectRatio="none" role="img" aria-label="Map of tracked sanctions targets and issuer links">'+arcs+pts+'</svg>';}
