  function feedRows(list){if(!list.length)return'<tr><td class="snw-empty" colspan="6">No sanctions programme matches these filters</td></tr>';return list.map(function(p){return'<tr tabindex="0" draggable="true" data-snw-drag="1" data-snw-id="'+esc(p.id)+'" aria-label="Drag '+esc(p.name)+' to AI Research" class="'+(selected&&p.id===selected.id?'snw-selected':'')+'"><td title="'+esc(p.name)+'">'+esc(p.name)+'</td><td title="'+esc(p.issuer)+'">'+esc(p.issuer)+'</td><td title="'+esc(p.sectors.join(', '))+'">'+esc(p.sectors.slice(0,2).join(' · '))+'</td><td class="snw-count">'+esc(p.entities)+'</td><td><span class="snw-status" data-status="'+esc(p.status)+'">'+esc(p.status)+'</span></td><td class="snw-go">›</td></tr>';}).join('');}
