  function feedHtml(){return'<section class="snw-feed"><div class="snw-command"><div><h3>Sanctions monitor</h3><p>Programme register · official-source links · selected issuer-to-target route</p></div><div class="snw-stats"><div class="snw-stat"><strong>'+DATA.length+'</strong><span>regimes</span></div><div class="snw-stat"><strong>'+countIssuers()+'</strong><span>issuer groups</span></div><div class="snw-stat"><strong>'+regions().length+'</strong><span>regions</span></div></div></div><div class="snw-tools"><input class="snw-search" type="search" placeholder="Search programme, issuer or sector" aria-label="Search sanctions regimes"><select class="snw-select snw-region">'+options(regions(),'All regions')+'</select><select class="snw-select snw-type-filter">'+options(types(),'All regime types')+'</select><select class="snw-select snw-status-filter">'+options(['active','escalating','under-review'],'All statuses')+'</select></div><div class="snw-mapframe"><div class="snw-map"><span class="snw-maplabel">Selected issuer-to-target route</span>'+mapSvg()+'<div class="snw-mapkey"><span><i class="snw-dot red"></i>Selected</span><span><i class="snw-dot"></i>Tracked target</span></div></div><aside class="snw-mapcard">'+mapCardHtml()+'</aside></div><div class="snw-result"><span><b data-snw-count>'+DATA.length+'</b> programmes</span><span>Select a programme for analysis</span></div><div class="snw-tablewrap"><table class="snw-table"><colgroup><col style="width:25%"><col style="width:24%"><col style="width:25%"><col style="width:13%"><col style="width:10%"><col style="width:3%"></colgroup><thead><tr><th>Programme / target</th><th>Issuing authorities</th><th>Economic perimeter</th><th style="text-align:right">Listed scope</th><th>Status</th><th></th></tr></thead><tbody>'+feedRows(DATA)+'</tbody></table></div></section>';}
  function rankedCounts(values){var counts={};values.forEach(function(v){if(v)counts[v]=(counts[v]||0)+1;});return Object.keys(counts).map(function(k){return{name:k,count:counts[k]};}).sort(function(a,b){return b.count-a.count||a.name.localeCompare(b.name);});}
