  function portfolioBars(items,limit){var list=items.slice(0,limit||5),max=list.reduce(function(m,x){return Math.max(m,x.count);},1);return'<div class="snw-port-bars">'+list.map(function(x){return'<div class="snw-port-row"><label title="'+esc(x.name)+'">'+esc(x.name)+'</label><span class="snw-port-track"><i class="snw-port-fill" style="width:'+Math.max(6,Math.round(x.count/max*100))+'%"></i></span><strong>'+x.count+'</strong></div>';}).join('')+'</div>';}
  function analyticsWorkspaceHtml(p){var regionCounts=rankedCounts(DATA.map(function(x){return x.region;})),issuerCounts=rankedCounts([].concat.apply([],DATA.map(issuerTokens)));return'<div class="snw-selection-strip"><i></i><div><h2>'+esc(p.name)+'</h2><p>'+esc(p.region)+' · '+esc(p.type)+' · '+esc(p.target)+'</p></div><span class="sna-status">'+esc(p.status)+'</span></div><div class="snw-portfolio-kpis"><div class="snw-portfolio-kpi"><label>Regimes tracked</label><strong>'+DATA.length+'</strong><span>Source-linked programme records</span></div><div class="snw-portfolio-kpi"><label>Issuer groups</label><strong>'+countIssuers()+'</strong><span>Recorded issuing jurisdictions</span></div><div class="snw-portfolio-kpi"><label>Target regions</label><strong>'+regions().length+'</strong><span>Normalized programme geography</span></div><div class="snw-portfolio-kpi"><label>Sector families</label><strong>'+sectorFamilyCount()+'</strong><span>Named restricted sectors</span></div></div><div class="snw-visual-grid"><div class="snw-map"><span class="snw-maplabel">Issuer-to-target routes · selected: '+esc(p.name)+'</span>'+mapSvg()+'<div class="snw-mapkey"><span><i class="snw-dot red"></i>Selected programme</span><span><i class="snw-dot"></i>Tracked target</span></div></div><aside class="snw-chart-stack"><div class="snw-port-chart"><div class="snw-port-chart-head"><b>Programmes by target region</b><span>Record count</span></div>'+portfolioBars(regionCounts,5)+'</div><div class="snw-port-chart"><div class="snw-port-chart-head"><b>Issuer group presence</b><span>Programme count</span></div>'+portfolioBars(issuerCounts,5)+'</div></aside></div>'+analyticsHtml(p);}
  function primarySource(p){return p.sources[0]||['Official source','https://ofac.treasury.gov/'];}
