  function cardFor(p){return{title:p.name,feature:FEATURE,tier:'geopolitics',tierLabel:'Global',bucket:'Diplomacy & Sanctions',csv:'niy_sanctions_enriched',__snId:p.id,source:primarySource(p)[1],fields:{Programme:p.name,Region:p.region,Status:p.status,'Regime type':p.type,Target:p.target,Objective:p.reason,'Issuing authorities':p.issuer,'Legal basis':p.basis,'Listed scope':p.entities,Sectors:p.sectors.join('; '),Instruments:p.instruments.join('; '),'Licences / exceptions':p.exemptions.join('; '),'Enforcement watch':p.watch.map(function(x){return x[0]+': '+x[1]+' — '+x[2];}).join(' | '),'Market transmission':p.market.map(function(x){return x[0]+': '+x[1];}).join(' | '),'Decision trail':p.trail.map(function(x){return x[0]+': '+x[1];}).join(' | '),'Primary source':primarySource(p)[1]}};}
  function researchPrompt(p){return'Research the '+p.name+' sanctions programme using the attached source-linked record. Verify the programme against the latest official issuer registers and legal texts. Return: current legal authorities; active designation and ownership rules; exact sectoral prohibitions; general and specific licences; humanitarian exceptions; latest additions, removals and enforcement actions; known evasion typologies with attributable evidence; exposed sectors and third-country pathways; and a dated source list. Separate issuer regimes where rules differ. Do not infer an intensity, effectiveness, probability, compliance or economic-loss score, and do not treat listed scope as a risk score.';}
  function refreshAiContext(){var detail=document.getElementById('detail'),has=!!(window.NiyAI&&Array.isArray(window.NiyAI.cards)&&window.NiyAI.cards.length);if(detail)detail.classList.toggle('snw-ai-has-context',has);var context=document.querySelector('#detail .niy-pane-ai .niy-ai-context');if(context)context.hidden=!has;}
