  function directResearchHtml(p){return'<div class="snw-direct-research"><header class="snr-head"><i class="snr-mark"></i><div><h2>AI Research · '+esc(p.name)+'</h2><p class="snr-sub">Source-linked regime context · verification required</p></div></header><div class="snr-brief">'+esc(analyticalBrief(p))+'</div><label class="snr-label">Research paths</label><div class="snr-prompts"><button type="button" data-snw-direct-prompt="Verify the latest official designations, delistings, general licences and enforcement actions across every issuing authority.">Verify latest changes</button><button type="button" data-snw-direct-prompt="Map ownership, control, intermediaries and third-country circumvention pathways with attributable evidence only.">Trace evasion network</button><button type="button" data-snw-direct-prompt="Compare the exact prohibitions, exemptions and ownership rules across the issuing jurisdictions.">Compare issuer rules</button><button type="button" data-snw-direct-prompt="Assess exposed sectors and market transmission without inventing quantified losses or effectiveness scores.">Map sector exposure</button></div><label class="snr-label">Attached record</label><div class="snr-sourcebox"><div><label>Programme</label><span>'+esc(p.name)+'</span></div><div><label>Legal basis</label><span>'+esc(p.basis)+'</span></div><div><label>Issuers</label><span>'+esc(p.issuer)+'</span></div><div><label>Primary source</label><span>'+esc(primarySource(p)[0])+'</span></div></div><button type="button" class="snr-open" data-snw-research>Open AI Research</button><span class="snr-note">The research request carries the selected regime, legal perimeter, measures, exemptions, enforcement watch and source link.</span></div>';}
